import{at as e,it as t,n,vt as r}from"./chunks/framework.DbV_8hbX.js";import"./chunks/assets.ByxXdwmG.js";var i=JSON.parse(`{"title":"施策を作成・配信する","description":"","frontmatter":{},"headers":[],"relativePath":"guides/campaigns.md","filePath":"guides/campaigns.md","lastUpdated":1794405326000}`),a={name:`guides/campaigns.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="施策を作成・配信する" tabindex="-1">施策を作成・配信する <a class="header-anchor" href="#施策を作成・配信する" aria-label="Permalink to “施策を作成・配信する”">​</a></h1><p>「施策一覧」で、停止中・下書きを含む施策を確認できます。「新しい施策」から、対象者、表示内容、配信設定の順に設定します。編集者以上の権限が必要です。</p><h2 id="_1-施策名を付ける" tabindex="-1">1. 施策名を付ける <a class="header-anchor" href="#_1-施策名を付ける" aria-label="Permalink to “1. 施策名を付ける”">​</a></h2><p>施策名は管理用です。サイト上の「表示タイトル」とは別です。例として「夏のポロシャツ特集」と付けます。</p><h2 id="_2-条件ノードを編集する" tabindex="-1">2. 条件ノードを編集する <a class="header-anchor" href="#_2-条件ノードを編集する" aria-label="Permalink to “2. 条件ノードを編集する”">​</a></h2><p>新規作成も再編集も、ノードを線でつなぐ画面で設定します。最初はJev条件が1つ、最終結果へ接続されています。ノードの「編集」で入力し、「変更を保存」で図へ反映します。右の「条件の編集」から直接修正することもできます。</p><p><img src="/jev-personalization/images/condition-nodes.png" alt="URL条件とJevの判定をORでつなぐ画面" width="924" height="1396"></p><h3 id="jevで関心・状態を判断する" tabindex="-1">Jevで関心・状態を判断する <a class="header-anchor" href="#jevで関心・状態を判断する" aria-label="Permalink to “Jevで関心・状態を判断する”">​</a></h3><p>「何を伝えたいですか？」には案内する内容を書きます。</p><blockquote><p>吸汗速乾ポロシャツの特集を案内する</p></blockquote><p>「どんな人に届けたいですか？」には判断したい1つの関心・状態を書きます。</p><blockquote><p>吸汗速乾機能のあるポロシャツに関心がある</p></blockquote><p>どちらも各400文字以内です。商品画像や表示用HTMLではなく、判定の文脈を説明します。</p><h2 id="_3-実際の質問を確認する" tabindex="-1">3. 実際の質問を確認する <a class="header-anchor" href="#_3-実際の質問を確認する" aria-label="Permalink to “3. 実際の質問を確認する”">​</a></h2><p>入力を固定の型に当てはめて表示します。生成AIによる文章変換は行いません。</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>今回案内する内容：吸汗速乾ポロシャツの特集を案内する</span></span>
<span class="line"><span>現在ページ・流入ページ・有効な過去の閲覧履歴と連携された行動・状態の情報に基づき、この閲覧者に「吸汗速乾機能のあるポロシャツに関心がある」が当てはまりますか？</span></span></code></pre></div><p>意図に合わない場合は入力文を修正します。漠然とした「よさそうな人」「買ってくれそう」ではなく、何に関心があるか、どんな状態を判断したいかを書いてください。</p><table tabindex="0"><thead><tr><th>分野</th><th>案内する内容</th><th>判定する関心・状態</th></tr></thead><tbody><tr><td>BtoB</td><td>顧客情報共有の導入ガイド</td><td>複数部門での情報共有に課題がある</td></tr><tr><td>メディア</td><td>省エネ対策の記事特集</td><td>家庭向けの省エネ対策に関心がある</td></tr><tr><td>採用</td><td>開発組織の説明会</td><td>エンジニアの開発環境に関心がある</td></tr><tr><td>教育</td><td>初学者向け説明会</td><td>初心者向けの学習計画に関心がある</td></tr></tbody></table><h2 id="条件をつなぐ" tabindex="-1">条件をつなぐ <a class="header-anchor" href="#条件をつなぐ" aria-label="Permalink to “条件をつなぐ”">​</a></h2><p>「ノードを追加」からURL条件・Jev条件・AND・ORを追加します。出力はノードの下、入力は上の丸い端子です。出力から入力へドラッグするか、出力→入力の順にクリックして接続します。見出しをつかむとノードを移動できます。</p><ul><li><strong>URL条件</strong>：現在ページ・流入ページのURLやGETパラメータをコードで照合します。</li><li><strong>Jev条件</strong>：1つの関心・状態をYes/Noで判断します。別の質問の回答は参照しません。</li><li><strong>AND</strong>：接続した条件をすべて満たす場合に成立します。</li><li><strong>OR</strong>：接続した条件のどれかを満たす場合に成立します。</li><li><strong>表示対象の判定</strong>：最終結果です。入力は1本で、このノードは削除できません。</li></ul><p>例えば「メールの流入コードにrunnerを含む、またはポロシャツに関心がある」は、URL条件とJev条件をORへつなぎ、ORの出力を最終結果へ接続します。さらに「購入に向けて比較している」を必須にするなら、ORの結果ともう1つのJev条件をANDへつなぎます。</p><p>URLだけで結論が出る枝は、Jevへ問い合わせません。例えばORのURL条件が成立すれば、もう一方の関心の推論は不要です。Jevへ確認する場合も、結果に必要な質問を1回のリクエストへまとめます。各質問の判定値をしきい値と比較してAND/ORを評価し、確率同士は掛け合わせません。</p><p>AND・ORの入力は2本以上です。循環する線は接続できません。配信開始には、すべてのノードを最終結果へ接続する必要があります。1施策につきJevは5問、URLは5条件、全体で20ノード・40接続までです。サイト全体ではJevの質問は10問までです。</p><h3 id="修正・削除する" tabindex="-1">修正・削除する <a class="header-anchor" href="#修正・削除する" aria-label="Permalink to “修正・削除する”">​</a></h3><p>ノードの「削除」または右クリックのメニューで削除できます。線をクリックして「選択を削除」を押すと接続だけを外せます。「元に戻す」で直前の変更を戻せます。Deleteキーも使えます。移動で見づらくなった場合は「整列」や「全体」で調整します。</p><h3 id="サンプルで条件を試す" tabindex="-1">サンプルで条件を試す <a class="header-anchor" href="#サンプルで条件を試す" aria-label="Permalink to “サンプルで条件を試す”">​</a></h3><p>「この設定を試す」を押すと、入力したURLとJevの仮の判定値で、各ノードと最終結果を確認できます。Jev APIを呼ばず、利用回数や閲覧履歴も増えません。</p><ol><li>流入ページ・現在ページのURLを入力します。登録済みのオリジン・収集経路に含まれるURLを使います。</li><li>Jev条件ごとに0〜1の仮の判定値を入力します。空欄は情報不足です。</li><li>「テストを実行」を押します。「対象」「対象外」「情報不足」と、Jevへの確認が必要な質問数が分かります。</li></ol><p>サイトの除外キーは送信前にURLから取り除き、APIでも再確認します。条件・URL・判定値・しきい値を変えた場合は、もう一度テストしてください。</p><p>このテストは条件の組み合わせを確認するものです。Jevの実際の推論、同意・履歴数・配信ページ・表示回数の制約、オファーの見え方は<a href="./testing">動作確認とプレビュー</a>で別に確認します。入力欄の判定値は購入率や実測結果ではありません。</p><h2 id="対象者判定の厳しさ" tabindex="-1">対象者判定の厳しさ <a class="header-anchor" href="#対象者判定の厳しさ" aria-label="Permalink to “対象者判定の厳しさ”">​</a></h2><p>「対象者判定の厳しさ」は、次の3段階から選びます。初期設定は「標準」です。</p><table tabindex="0"><thead><tr><th>選択肢</th><th>意味</th><th>内部のしきい値</th></tr></thead><tbody><tr><td>広めに判定</td><td>当てはまる可能性がある人にも届ける</td><td>0.6</td></tr><tr><td>標準</td><td>関心・状態への当てはまりを標準的な基準で判断する</td><td>0.7</td></tr><tr><td>慎重に判定</td><td>当てはまると強く判断できる人に絞る</td><td>0.85</td></tr></tbody></table><p><img src="/jev-personalization/images/judgment-strictness.png" alt="対象者判定の厳しさを3段階から選ぶ画面" width="720" height="294"></p><p>慎重にするほど表示対象になりにくくなります。購入率や施策効果を設定するものではありません。他の配信条件によっても表示は制限されます。</p><p>細かく調整する場合は「詳細設定（しきい値を調整）」を開き、スライダーまたは数値入力を使います。既存の値が3段階のどれにも一致しない場合は「カスタム設定」として詳細を表示し、その値を保持します。選択肢へ自動で丸めることはありません。</p><p>しきい値は0.5〜0.99です。判定値が設定値を<strong>上回る</strong>場合に対象とします。たとえばしきい値0.70で判定値がちょうど0.70なら対象になりません。</p><h2 id="_4-表示コンテンツを用意する" tabindex="-1">4. 表示コンテンツを用意する <a class="header-anchor" href="#_4-表示コンテンツを用意する" aria-label="Permalink to “4. 表示コンテンツを用意する”">​</a></h2><p>形式を選び、表示タイトル・メッセージ・ボタン・リンク・画像を設定します。<a href="./presentation">表示形式</a>に詳細をまとめています。</p><p><img src="/jev-personalization/images/campaign.png" alt="施策の表示コンテンツ" width="1440" height="1384"></p><h2 id="_5-配信設定" tabindex="-1">5. 配信設定 <a class="header-anchor" href="#_5-配信設定" aria-label="Permalink to “5. 配信設定”">​</a></h2><table tabindex="0"><thead><tr><th>項目</th><th>意味</th></tr></thead><tbody><tr><td>表示するページ</td><td>全許可ページ、完全一致、前方一致。パスで指定</td></tr><tr><td>表示回数の上限</td><td>ブラウザの有効な履歴内の上限</td></tr><tr><td>優先順位</td><td>複数対象の場合、大きい値を優先</td></tr><tr><td>除外する確定状態</td><td>登録済みfactがtrueなら除外</td></tr></tbody></table><p>除外状態を指定した場合、値が不明なまま対象とは扱いません。未完了ならfalse、完了したらtrueを<a href="./../integration/sdk">SDK</a>から明示して連携します。</p><h2 id="_6-下書き保存と配信開始" tabindex="-1">6. 下書き保存と配信開始 <a class="header-anchor" href="#_6-下書き保存と配信開始" aria-label="Permalink to “6. 下書き保存と配信開始”">​</a></h2><p><strong>下書き保存</strong>では編集中の内容を保存します。公開中の施策を編集しても、以前の配信内容は維持します。途中の入力も保存できます。</p><p>「配信内容を確認」を押し、内容を確認してから「この内容で配信開始」を押すと、公開設定へ反映されます。未入力の判定条件や表示タイトルがあれば開始できません。</p><p>配信前は一覧の<a href="./testing">プレビュー</a>から実ページで確認してください。停止・再開は一覧から行います。</p><h2 id="同時編集で競合した場合" tabindex="-1">同時編集で競合した場合 <a class="header-anchor" href="#同時編集で競合した場合" aria-label="Permalink to “同時編集で競合した場合”">​</a></h2><p>別の変更を上書きしないよう、古い編集内容の保存・配信は受け付けません。一覧を読み直し、最新の内容を確認します。必要な入力を控えたうえで下書きを破棄し、最新内容から編集し直してください。</p><h2 id="既存施策とjson編集" tabindex="-1">既存施策とJSON編集 <a class="header-anchor" href="#既存施策とjson編集" aria-label="Permalink to “既存施策とJSON編集”">​</a></h2><p>既存施策を開くと、登録済みのURL条件と質問を、元のAND/ORの意味を保ってノードへ表示します。質問ID・原文・案内内容を保持し、保存するまでは配信設定を変更しません。独自の質問は「判定質問（原文）」で編集できます。原文は共通の案内内容を変更しても自動では変わりません。</p><p>「条件グラフのJSONを見る」から保存形式を確認し、「JSONで編集」でコピー・貼り付けや直接編集ができます。「JSONを反映」ではIDや接続先、循環を検証します。不正なJSONで図を置き換えることはありません。配信には、別途「下書き保存」「配信内容を確認」が必要です。</p><h2 id="urlの条件で対象を絞る" tabindex="-1">URLの条件で対象を絞る <a class="header-anchor" href="#urlの条件で対象を絞る" aria-label="Permalink to “URLの条件で対象を絞る”">​</a></h2><p>「URL条件」ノードで、現在ページまたは流入ページのGETパラメータ・URL全体を条件にできます。例えば、メールからの流入を識別するには次のように設定します。</p><table tabindex="0"><thead><tr><th>項目</th><th>設定例</th></tr></thead><tbody><tr><td>対象のページ</td><td>流入ページ（同意後の初回）</td></tr><tr><td>調べる値</td><td>GETパラメータの値</td></tr><tr><td>GETパラメータのキー</td><td><code>cid</code></td></tr><tr><td>一致の方法</td><td>含む</td></tr><tr><td>比較する値</td><td><code>runner</code></td></tr></tbody></table><p>この条件はJevへ質問せず、コードで照合します。GETパラメータはデコードした値に照合し、大文字小文字を区別します。同じキーの値が複数あれば1つでも一致すると成立します。URL条件はAND/ORノードで組み合わせます。サイトの除外キーに含めた値は使えません。</p><p>関心・状態も推論したい場合は、Jev条件とAND/ORでつなぎます。URL条件だけを最終結果へつなぐ施策では、Jevへの問い合わせや判定しきい値は使いません。URL条件のパラメータやURLがない場合は、その条件は不成立です。</p><p><strong>判定に必要な過去の有効閲覧数</strong>は、新しい施策では0件です。流入条件だけで初回表示したい場合は0件にします。過去の閲覧を必要とする施策では件数を指定するか、サイト設定を使います。現在ページは過去の有効閲覧に数えません。既存施策の未指定値はサイト設定を維持します。</p>`,59)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};